import {architectureSources,architectureUpdated} from './architecture-sources.js';
export {architectureSources,architectureUpdated};
// Group = learning location; axis = the design decision, used to warn about unlike comparisons.
export const architectureGroups=[
 {id:'skeleton',name:'整体骨干与计算组织',axis:'整体组织',question:'输入、输出和层之间怎样连接？',lesson:'foundation',projects:['pretrain','world-model']},
 {id:'attention',name:'全注意力与 KV 表示',axis:'序列交互',question:'历史怎样被读取，K/V 怎样保存？',lesson:'attention',projects:['pretrain','systems']},
 {id:'sparse',name:'窗口、稀疏与压缩注意力',axis:'序列交互',question:'读哪些历史位置，省掉什么工作？',lesson:'sparse',projects:['memory','systems']},
 {id:'approximation',name:'低秩、哈希与核近似',axis:'序列交互',question:'能否近似原来的全连接计算？',lesson:'alternatives',projects:['memory']},
 {id:'state',name:'循环、线性注意力与 SSM',axis:'序列交互',question:'能否把历史写成固定大小的状态？',lesson:'state',projects:['memory','world-model']},
 {id:'capacity',name:'FFN、MoE 与条件记忆',axis:'参数容量',question:'每个 token 调用哪些参数？',lesson:'capacity',projects:['pretrain','systems']},
 {id:'scaffold',name:'位置、归一化与残差',axis:'层内支撑',question:'顺序和信号怎样穿过深层网络？',lesson:'capacity',projects:['pretrain','omnifm']},
 {id:'vision',name:'视觉表示与跨模态接口',axis:'感知接口',question:'像素怎样成为可用的表示？',lesson:'vision',projects:['vision','omnifm']},
 {id:'generation',name:'图像、视频与文本生成骨干',axis:'生成系统',question:'在哪个空间、用怎样的网络生成？',lesson:'generation',projects:['flow','vision']},
 {id:'embodied',name:'世界模型、动作与策略结构',axis:'具身系统',question:'预测环境还是生成行动？',lesson:'embodied',projects:['world-model','planning','omnifm']},
 {id:'execution',name:'执行、缓存与推测解码',axis:'执行实现',question:'怎样在硬件上运行同一个计算？',lesson:'evaluation',projects:['systems']},
];
const item=(id,name,group,purpose,mechanism,cost,experiment,sources)=>({id,name,group,purpose,mechanism,cost,experiment,sources,axis:architectureGroups.find(g=>g.id===group).axis});
export const architectures=[
 item('transformer','Transformer','skeleton','把序列中的信息交互和每个位置的特征加工分开组织。','一个典型 block 含 token mixer（注意力）、逐位置 FFN、归一化和残差。把许多 block 叠起来，再接输入嵌入与输出头；它是结构家族，不是一种训练阶段。','深度、宽度、头数和 FFN 都影响参数与激活。某处替换注意力并不等于整个系统不再具有 Transformer 风格。','沿一条样本标注 [B,T,D]，分别指出哪一步混合 token、哪一步只变换通道。',['transformer']),
 item('encoder-only','Encoder-only','skeleton','读取一份完整输入，学习适合分类、检索或表示的特征。','常见文本 encoder 使用双向 self-attention：一个词可以借助左右两侧输入。输出可取某个位置或池化表示。BERT 的预训练目标与这种可见性相配合。','双向读取已知输入很方便；把未来目标也放进输入，会让因果预测泄漏答案。','写出三词输入的全可见矩阵，再说明为什么它不能直接用于同一段文字的 next-token 训练。',['bert']),
 item('decoder-only','Decoder-only','skeleton','用已有前缀逐步预测后续 token，统一训练与生成接口。','常见 AR 实现只使用因果 self-attention block；位置 t 只能读取不晚于 t 的输入，训练标签通常右移一位。可以把视觉、动作等表示接入同一因果骨干。','训练仍可对多个位置并行计算；生成通常逐步进行。Decoder-only 不自动说明用 GQA、DSA 还是 KDA，也不代表一定是语言任务。','固定前缀、更改未来输入，检查前缀输出不变；把这一检查用到 P01 和 P06。',['transformer','llama']),
 item('encoder-decoder','Encoder–Decoder','skeleton','把理解输入和生成输出拆成两个可单独设计的部分。','encoder 编码输入，decoder 既做目标侧因果 self-attention，又用 cross-attention 读取 encoder 表示。T5 是文本实例；不能仅凭“有编码器和解码器”判断两个模块内部结构。','输入可编码一次，但增加交叉注意力和两套接口。和单栈方案比较时要匹配参数、数据与生成预算。','画出 source tokens、target tokens 和 cross-attention 的 Q/K/V 分别来自哪里。',['t5','transformer']),
 item('ced','CED · 因果编码器—解码器','skeleton','重新安排因果编码与全局缓存来源，优化特定输入输出负载。','DeepSeek-V4.1-Flash 的公开 CED 设计让 decoder 的全局 KV 来自最终 encoder 表示；encoder 也保持因果性。它与 T5 式双向源编码器不是同一接口。','这是版本特定设计，涉及跨层缓存共享和 prefill/decode 工作分配，不能靠给普通模型改一个名称实现。','对照官方模型卡，画两张图：逐层自己生成 KV，以及 decoder 读取 encoder 生成的全局 KV。',['v41']),
 item('hybrid','混合骨干 · Hybrid','skeleton','在同一系统中组合不同计算路径，平衡精细检索、状态记忆和成本。','可以按层交替，也可在层内并联。Kimi Linear 把 KDA 与 MLA 交替；Qwen3-Next 把 Gated DeltaNet 与 gated attention 组合。MoE 又是另一个可叠加的轴。','混合模型仍有完整注意力层时，不能宣称整个模型缓存恒定；层比例、位置与实际 kernel 都会改变效果。','只改变全局层比例，记录任务质量、全部状态字节数、prefill 和 decode 时间。',['kimi','qwenNext']),
 item('universal','Universal / Looped Transformer','skeleton','复用参数，在深度方向反复加工同一批表示。','普通堆叠用不同层权重；循环深度模型复用变换，多次细化 hidden states。这里的“循环”沿计算深度，不等同于 KDA 沿 token 时间更新状态。','参数可以较少，但多次迭代仍消耗算力和延迟。训练时的步数与测试时增加步数能否兼容，需要实验。','保持权重共享，比较执行 1、2、4 次的质量与时延，报告实际计算量。',['ut']),
 item('recursive','HRM / TRM · 递归细化路线','skeleton','让小网络通过反复更新潜在解，完成特定推理任务。','这条路线研究计算深度和状态细化。TRM 将递归推理组织得更简洁；具体训练、停止与监督规则同样关键，不能把结果仅归因于模型小或名字中的层次。','任务设置、数据量和测试计算与通用聊天模型不同。单一谜题成绩不能证明它全面替代大语言模型。','分别消融共享迭代、监督方式和计算步数，再看泛化到未见任务的表现。',['trm','ut']),
 item('mha','MHA · 多头注意力','attention','让不同查询子空间分别读取历史信息。','每个查询头有自己的 K/V 头，先算相似度、按可见位置 softmax，再加权聚合 V。输出拼接后投影。因果 mask 和头的存储方式是不同设计轴。','固定宽度下，稠密 prefill 的位置对数量随 T² 增长；decode 的 KV 缓存随 T 增长。FlashAttention 可以省 IO，却不会把数学上的全连接改成稀疏。','用 4 个二维向量手算一次 softmax 聚合；再把某个未来位置屏蔽。',['transformer']),
 item('mqa','MQA · 多查询注意力','attention','减少逐 token 生成时需要保存和读取的 K/V。','保留多个 Q 头，但所有查询头共享一组 K/V。它改变 K/V 表示的共享程度，不会自动缩小每个查询可见的历史范围。','缓存变小，也压缩了不同头独立表示历史的自由度。不能假设任意 MHA checkpoint 无训练替换后质量不变。','同一 B、L、T、头维度下计算 MHA 与 MQA 的 KV 字节数；再比较任务质量。',['mqa']),
 item('gqa','GQA · 分组查询注意力','attention','在 MHA 的多组 K/V 与 MQA 的一组 K/V 之间折中。','把 Q 头分组，每组共享一个 K/V 头。h_kv=h_q 是 MHA 的端点，h_kv=1 是 MQA 的端点；中间值是常见 GQA。','KV 内存依赖 KV 头数，QK 交互仍发生在所有查询头。分组不能直接等比例降低端到端运行时间。','设置 32 个 Q 头，比较 32、8、1 个 KV 头；核对缓存公式中的 h 应取哪一个。',['gqa']),
 item('mla','MLA · 多头潜在注意力','attention','压缩每个历史位置需要保留的 K/V 信息。','将 K/V 联合表示成低维潜变量，并为位置相关部分采用专门处理。优化后的推理实现可利用投影吸收，避免把全部展开 K/V 长期保存。','MLA 的低秩在特征维度上；序列中每个位置仍有缓存。它不同于删掉历史 token，也不同于 LoRA 的训练增量。','检查缓存里实际保存的是潜变量、位置分量还是展开 K/V；按真实 layout 统计内存。',['mla']),
 item('gated-attention','Gated Attention · 注意力输出门','attention','控制注意力读出的信息有多少进入后续计算。','在注意力输出等位置引入输入依赖的门。它仍可使用 softmax attention；“有 gate”不意味着已经变成线性注意力或固定状态模型。','额外非线性会改变表达与稳定性；门放在哪里、按头还是按通道，都需要对照。','在同一注意力输出后加 gate，观察门分布、梯度和质量；不要把这个门与 KDA 的遗忘门混为一谈。',['gatedAttention']),
 item('swa','SWA · 滑动窗口注意力','sparse','限制每个位置只读取附近历史，减少长序列的直接交互。','因果窗口 W（本课程包含当前位置）让 t 读取 max(0,t-W+1)…t。多层堆叠可间接传递更远信息，但这不等于每层可直接检索全部过去。','固定 W 时主注意力约 O(TW)。只有实际淘汰窗口外 KV，且没有全局层或其他保留机制，才获得窗口有界缓存。','令 T=6、W=3，画出带状 mask；在序列开头放一条关键事实，再测很远处能否取回。',['mistral','longformer']),
 item('longformer','局部＋全局注意力 · Longformer','sparse','在局部窗口之外，为任务保留少量远距离信息通道。','大多数位置做局部读取，指定全局 token 负责跨远距离汇聚。全局 token 是结构选择，不代表其他位置直接看到了完整历史。','全局位置数量增加也会增加成本。论文的双向文档编码设置与因果生成设置必须区分。','比较无全局位置与一个全局位置的可达性图；做生成任务时重新检查因果性。',['longformer']),
 item('bigbird','BigBird · 局部＋随机＋全局','sparse','通过少量额外边改善稀疏图的远距离连通。','结合邻近窗口、随机连接和全局 token。随机边不是按当前内容学习出来的 Top-k，因此和 DSA 的索引器是不同机制。','稀疏图的理论性质不等于所有实际任务零损失；实现的块大小、随机种子与布局都影响成本。','固定总连接预算，比较只有窗口与加入随机远边的多跳可达性。',['bigbird']),
 item('longnet','Dilated Attention · LongNet','sparse','用不同尺度与间隔覆盖很长的序列。','在分段内按膨胀间隔抽样交互，再组合不同粒度。它通过连接模式扩大覆盖，而不是把所有历史都写进一块循环矩阵。','跳采样会改变局部细节和信息路径；大上下文支持不代表任意长距离检索都准确。','画出间隔 1、2、4 的连接图，用同一检索任务比较遗漏位置的影响。',['longnet']),
 item('nsa','NSA · 原生稀疏注意力','sparse','同时保留粗粒度全局信息、选中块的细节和近邻信息。','组合压缩、选择、滑窗三条注意力分支，并考虑块布局与硬件实现。它与 DSA 同属稀疏路线，但不是 DSA 的同义词。','分支融合、选择粒度和 kernel 决定真实收益；不能只凭少算了多少位置对推断速度。','把一篇文档画成压缩摘要、精选原文块和最近窗口，分别删除一个分支观察失败。',['nsa']),
 item('moba','MoBA · 块路由注意力','sparse','按内容选择需要读取的历史块。','先把历史分块，使用块级路由决定每个查询要访问哪些块，再在所选块内计算注意力。借鉴 MoE 的路由思想，路由对象却是 token 块。','MoBA 的稀疏在序列位置维度；MoE 的稀疏在专家参数维度，两者可以组合。块越大越省路由但选择越粗。','同一个问题用不同块大小选择上下文，检查关键事实是否随整个块被保留。',['moba']),
 item('dsa','DSA · DeepSeek Sparse Attention','sparse','让昂贵的主注意力只精读被筛选的历史位置。','在 DeepSeek-V3.2 的实例中，lightning indexer 给因果历史打分，取 Top-k，再读取 MLA 缓存做主注意力。索引分数不直接代替最终 attention 权重。','主注意力位置对约 O(Tk)，但原版索引器的全序列打分仍有 O(T²) 项。历史 KV 和索引 K 仍要保存，不能说整个模型是恒定缓存。','构造一个未来位置分数最高的例子，先做因果过滤再 Top-k；比较不同 k 的选择召回与输出误差。',['dsa','dsaCode']),
 item('csa','CSA · 压缩后再稀疏选择','sparse','同时减少历史条目数和每次精读的条目数。','DeepSeek-V4 的 CSA 先沿序列维压缩 KV，再进行 DSA 选择，并结合局部窗口。它与 MLA 压缩特征维度的操作位置不同。','压缩会损失细节，选择也可能漏信息；成本需要把压缩、索引、局部与全局分支都计入。','分别画出“每条变窄”和“多条合一”；测依赖单个精确细节的检索任务。',['v4']),
 item('hca','HCA · 强压缩注意力','sparse','用更少的全局摘要保留较宽的历史覆盖。','DeepSeek-V4 中对历史更强地压缩，然后对压缩条目做稠密注意力；与 CSA 交替使用。稠密的是压缩后的条目，不是所有原 token。','更强压缩换来更低资源，代价是细节容量。常数压缩率仍留下随长度增长的缓存。','比较同样缓存预算下更多细条目与更少粗摘要，对局部细节和全局趋势分别评测。',['v4']),
 item('csa2','CSA2 · 跨层共享与复用','sparse','进一步减少重复缓存与多层重复索引工作。','DeepSeek-V4.1-Flash 的公开设计区分 Full、Reindex、Reuse 模式，并使用分层候选筛选。名称相近不表示与 V4 的 CSA 配置可直接互换。','跨层共享增加实现约束；必须核对哪些层重算 KV、哪些层只重算索引、哪些直接复用。','从配置标出三种层模式，用一条 token 的路径说明数据由哪一层生产、哪一层消费。',['v41']),
 item('qsa','QSA · Qwen Sparse Attention','sparse','通过压缩索引和微块选择降低长上下文精读成本。','Qwen3.8-Flash-Next 的公开说明将 QSA 与 Gated DeltaNet 组合：一个保留可选择的历史，一个持续压缩记忆。具体实现以该版本为准。','微块选择不同于逐 token 选择。不要把项目名 QSA 当成所有稀疏 attention 的统一接口。','在模型拆解中同时标出 GDN 状态和 QSA 缓存，解释为什么混合后的总状态不恒定。',['qsa']),
 item('msa','MSA · MiniMax Sparse Attention','sparse','在 GQA 基础上，用块级选择降低长序列读取量。','MSA 将轻量索引和主注意力分开，先选择相关历史块，再精读所选区域。与 MoBA、DSA 都有关联，但选择粒度和训练细节不同。','缓存共享、块大小和索引成本需要一起测量；不能把不同模型报告的加速倍数直接放进同一排名。','统一数据、序列长度和硬件，比较索引时间与主注意力时间占比。',['msa']),
 item('linformer','Linformer · 序列低秩','approximation','以较少代表位置近似完整的序列交互。','对 K/V 的序列长度维做投影，将 T 个位置压到较短表示。它是序列维的近似，不是 MLA 的逐位置潜变量，也不是 LoRA 的权重增量。','低秩假设、长度绑定和因果实现都会影响质量与适用性；不能直接用双向压缩读取未来目标。','比较原注意力矩阵与低秩近似误差，专门加入稀有关键位置测试。',['linformer']),
 item('performer','Performer · 核近似','approximation','用随机特征近似 softmax 核，避免显式建立完整注意力矩阵。','通过特征映射和矩阵乘法重结合，将两两交互转成可累积统计。随机特征数量控制近似精度和成本。','近似误差、归一化和数值稳定性必须测试；并不是与精确 softmax 完全一样的算法。','固定输入，对比不同特征数量、随机种子下与精确 attention 的输出差异。',['performer']),
 item('nystrom','Nyströmformer · 地标近似','approximation','用少量地标表示近似大规模注意力关系。','从序列提取代表性地标，利用较小矩阵重建近似交互。与按分数直接保留原位置的稀疏注意力不同。','地标代表性和求逆近似会影响误差；不能因为矩阵更小就忽略难样例。','放入一个只有单个位置包含答案的例子，检查地标汇聚是否把它稀释。',['nystrom']),
 item('reformer','Reformer · LSH 注意力','approximation','把可能相似的位置分到相同桶，减少全对全比较。','LSH 先用哈希近似定位候选邻居，再在候选中计算注意力；论文还研究可逆层降低训练激活保存。两种节省来自不同位置。','哈希、排序和重复候选也有开销；相似向量可能落到不同桶。','改变哈希轮数，记录候选召回、重复率与整体运行时间。',['reformer']),
 item('rnn','RNN / LSTM / GRU','state','用不断更新的隐状态表示过去。','h_t=f(h_{t-1},x_t)，门控变体控制保留、重置与写入。先理解这种时间接口，才能分清状态数值延续和训练梯度跨越多久。','状态固定不代表能无损记住无限历史；逐步依赖、长程梯度和容量是核心取舍。','同一轨迹比较正确延续状态、每步 reset、跨 episode 不 reset 三种情况。',['gru','mamba']),
 item('linear','线性注意力 · 核化 / 累积状态','state','把前缀的键值交互改写成可累计统计。','利用乘法结合次序，先累积映射后的 K 与 V，再用 Q 读取；具体形式可能还维护归一化统计。模型里的投影和其他层仍可以是非线性的。','“线性”通常指序列长度复杂度，不是整个神经网络只有线性变换。固定状态可能产生记忆干扰。','先累计两个 key-value 外积，再用 query 读取；重复相似 key，观察是否互相干扰。',['linear']),
 item('retnet','RetNet · Retention','state','为训练、流式推理和分块推理提供相互对应的计算形式。','retention 使用带衰减的键值交互，具有并行、递推和分块形式。不同头可使用不同记忆时间尺度。','多种计算形式需在数值误差范围内对齐；状态接口并不自动带来更快的真实 kernel。','同一组输入分别整段和分两块计算，比较所有输出与最终状态。',['retnet']),
 item('gla','GLA · 门控线性注意力','state','让模型按输入决定不同记忆分量的保留程度。','在矩阵状态更新中加入数据依赖遗忘门，并配套硬件友好的分块算法。门主要控制历史衰减，不等于 delta rule 的纠错写入。','更灵活的门需要考虑数值范围与并行算法；固定容量仍会发生压缩损失。','保持输入相同，分别设置统一衰减和通道衰减，检查哪些关联被保留下来。',['gla']),
 item('deltanet','DeltaNet · 纠错写入','state','避免同一个键重复写入时只会无限相加。','先用旧状态读取当前 key 的预测，再写入“目标 value 减旧预测”的残差。简单约定下 S_new=S+βk(v−Sᵀk)ᵀ。','可定向纠正关联，但不等于保留一份可逐条查阅的历史。key 的尺度、写入强度与状态精度都重要。','重复 key=[1,0]，把 value 从 2 改成 5；比较相加写入与 delta 写入。',['delta']),
 item('gdn','Gated DeltaNet · GDN','state','让状态既能忘掉过时内容，也能定向修正当前关联。','在 delta 更新前衰减旧状态。经典 GDN 的遗忘门按头是标量，同一头各通道共同衰减；写入门 β 控制修正幅度。','遗忘太强会丢长期事实，太弱会残留过时信息。它不同于 softmax attention 输出后的门控。','只更改 α，测一个很久未出现的键是否仍可读出，以及新值覆盖是否充分。',['gdn']),
 item('kda','KDA · Kimi Delta Attention','state','更细地控制有限记忆中哪些通道该忘、哪些该留。','在 KDA 的核心递推中，以通道向量 α 衰减状态，再用 delta rule 纠错写入。它扩展 GDN 的遗忘粒度；完整模型还包含投影、归一化等组件。','固定尺寸的是单个 KDA 层的循环状态。Kimi Linear 的 MLA 层仍保存历史；核心公式实现也不等于复现全部 KDA kernel。','用二维状态和不同通道衰减手算一次，再写代码验证分块延续与整段一致。',['kda','kimi']),
 item('gdn2','Gated DeltaNet-2','state','进一步分开“擦掉多少旧关联”和“写入多少新内容”。','公开论文在通道衰减之外，让擦除与写入使用更独立的门控。它与 KDA/GDN 具有退化关系，应按公式核对，而不是只看名字后面的 2。','这是较新的研究路线；门的自由度、数值稳定性和 chunk 实现都需要实验。论文设置下的优势不代表所有规模、硬件和任务都胜出。','把不同门约束成同一个标量，检查是否退化到相应基线，再恢复独立门做对照。',['gdn2']),
 item('ssm','SSM · 状态空间模型家族','state','用状态转移和观测读出描述随时间变化的信息。','离散形式可写成 h_t=A_t h_{t-1}+B_t x_t，y_t=C_t h_t。SSM 是广泛家族；矩阵是否固定、结构化或依赖输入，决定不同方法的特性。','不是所有 SSM 都是 Mamba，也不是所有 RNN 都采用同一 SSM 参数化。固定状态和精确检索历史之间存在取舍。','先用一维 h_t=0.8h_{t-1}+x_t 看衰减，再比较输入依赖的保留系数。',['s4','mamba']),
 item('s4','S4 · 结构化状态空间','state','通过特殊参数结构，让长序列状态空间计算更可行。','S4 研究结构化状态转移、稳定参数化以及递推和卷积视角。它是理解现代 SSM 的基础路线，不是单纯把 attention 名称换成 RNN。','结构约束帮助计算，也限制自由度。训练卷积形式与流式递推形式的效率可能不同。','把相同线性系统展开成输入加权和，核对递推与卷积视角给出相同结果。',['s4']),
 item('mamba','Mamba · 选择性 SSM','state','按当前输入选择记住或忽略哪些信息。','将部分状态空间参数变成输入依赖，并配合 selective scan。相比固定动态，模型能根据内容改变状态更新。','输入依赖意味着不能直接套用所有固定卷积技巧。扫描 kernel、激活内存和状态容量都需要一起看。','给相同内容加不同干扰长度，观察选择性保留能否保住任务相关状态。',['mamba']),
 item('mamba2','Mamba-2 · SSD','state','用状态空间对偶连接特定 SSM 与结构化注意力计算。','SSD 建立特定结构矩阵的等价视角，支持更适合矩阵硬件的分块算法。论文标题的“Transformers are SSMs”不意味着任意 softmax attention 都可无损换成固定小状态。','表达约束与硬件效率相互影响；更快的核心层不一定直接等于训练整模同倍率加速。','核对同一算子的递推和分块输出，再单独计时核心层和整模。',['mamba2']),
 item('mamba3','Mamba-3 · 新的状态更新设计','state','改善状态跟踪能力，并围绕推理效率调整 SSM。','论文结合更丰富的离散递推、复数状态更新与 MIMO 形式。这里首先学习“如何增加状态表达能力”，再读具体参数化。','这是特定设计组合，不能把 Mamba-1 的 kernel、状态形状和性能结论直接沿用。','在状态跟踪和检索任务上，对齐状态大小、训练预算与 decode 条件后比较。',['mamba3']),
 item('rwkv','RWKV-7 · 动态矩阵状态','state','在保持递推接口的同时增强状态演化的表达能力。','RWKV 系列融合通道加工与时间状态；RWKV-7 使用更丰富的动态状态更新。它与线性注意力、delta 路线有联系，但公式与参数化并不相同。','不同 RWKV 代际也不应混成一个 kernel。固定状态不能保证任意长前缀精确检索。','先标明具体版本，再比较每层 state shape、更新公式与会话 reset 规则。',['rwkv']),
 item('hyena','Hyena · 长卷积与门控','state','通过长卷积和数据依赖门控建立长距离交互。','用隐式参数化的长滤波器与门控组合，绕开标准 attention 的显式两两 softmax。它是长序列计算的另一条路线。','长卷积在训练与单步生成中可能需要不同实现；理论次二次不自动说明低延迟。','比较局部模式和远距离关联任务，分别报告整段训练与增量生成效率。',['hyena']),
 item('transformer-xl','Transformer-XL · 片段循环记忆','state','让新片段能够读取前一片段的表示。','复用之前的 hidden states，并处理跨片段相对位置。它保留显式历史片段，与把全部历史压成固定矩阵状态不同。','缓存片段长度和反向传播范围是两个问题；读取旧表示不表示梯度跨越了所有历史。','分两段处理相同序列，检查旧片段是否 detach，以及第二段能看见哪些位置。',['txl']),
 item('ttt','TTT · 可学习隐状态','state','让隐状态由一个可随序列更新的小模型承载。','TTT 层用局部学习规则更新状态模型的权重；这些快速变化的状态与训练得到的慢参数有不同角色。它不是用户临时启动一次普通 SFT 的别名。','更新状态本身有计算成本，也涉及稳定性、重置与批处理。训练和推理需要匹配这套内部更新规则。','分别列出慢参数与快状态；切换独立样本时检查哪些必须重置。',['ttt']),
 item('titans','Titans · 测试时记忆模块','state','研究如何把短期注意力与可更新的长期记忆结合。','论文探索神经记忆与 attention 的不同组合位置。关键是明确记忆的读写、遗忘和学习信号，而不是把“长期”理解为无限无损保存。','属于研究结构方案，效果受任务、记忆容量与更新成本影响；不能和外部数据库 RAG 直接等同。','画出记忆写入和查询路径，把权重、会话状态、外部检索数据分别列清。',['titans']),
 item('dense-ffn','Dense FFN / MLP','capacity','在每个位置内部加工特征、增加非线性容量。','典型 FFN 先扩维、激活、再降维。同一层的各 token 共用这套权重，但 FFN 自身通常不在 token 之间交换信息。','FFN 可能占大量参数和 FLOPs。增加 FFN 宽度不等于增加可直接读取的上下文长度。','对调两个 token 的位置，观察逐位置 FFN 如何随之对调，而没有相互读取。',['transformer']),
 item('swiglu','SwiGLU / GLU','capacity','让特征加工包含逐通道的乘法门控。','SwiGLU 可理解为两条投影分支，其中一条经 SiLU，再逐元素相乘并投影回原宽度。它位于 FFN 内，不是对历史 token 的选择器。','参数量需按实际投影数计算；与普通 FFN 比较时应对齐参数或 FLOPs。','固定输入宽度，数出两输入投影与一输出投影的权重数量。',['swiglu']),
 item('moe','MoE · 混合专家','capacity','扩大总参数容量，同时只激活一部分专家计算。','router 为每个 token 选择若干专家 FFN，再组合输出。专家可以按 token 改变；shared experts 则可始终参与。','总参数影响存储，激活参数影响部分计算；路由、负载不均和跨卡通信使真实成本更复杂。MoE 不等于稀疏 attention。','统计每个专家接收的 token 数；构造全部 token 路由同一专家的极端情况。',['moe','mixtral']),
 item('shared-experts','细粒度＋共享专家','capacity','分开通用加工与按需调用的专家容量。','DeepSeekMoE 等设计使用较细的 routed experts 和 shared experts。粒度、激活数与共享容量共同构成配置，不只是一个“专家数”超参数。','增加专家总数不保证更多有效容量；必须看每 token 激活数、路由质量及通信。','对同一小批量列出 always-on 专家和 routed 专家，分别计算总参数与激活参数。',['mla','v3']),
 item('engram','Engram / N-gram 条件记忆','capacity','让部分局部模式通过查表获取，减轻网络重复计算。','Engram 的条件记忆和 N-gram embedding 路线按 token 上下文地址查询参数表。它是参数化的查表容量，不是运行时随历史累积的 KDA 状态。','表可能很大；地址、缓存、预取与主机内存带宽会影响收益。它与 MoE 条件计算可以互补。','把一次查表、一次专家选择、一次循环状态更新画成三条不同的数据路径。',['engram','qsa']),
 item('ngram','N-gram 条件嵌入','capacity','按局部离散组合查取额外表示，补充骨干计算容量。','Qwen3.8-Flash-Next 的公开说明包含 N-gram embedding 表；这是条件查表路线的具体实现。与 Engram 有相关设计动机，但不能认定二者实现相同。','表大小、哈希、碰撞、词表和读取带宽都会影响成本。未公开的实现细节不靠相似名称推断。','固定主干与数据，只开关额外查表分支，记录参数存储、读取成本和任务质量。',['qsa']),
 item('residual','Residual · 残差连接','scaffold','让深层计算能在保留原表示的基础上逐步修正。','最简单形式是 x+f(x)。它为信号和梯度提供直接路径；注意力与 FFN 通常被放在残差分支中。','残差不自动保证稳定，尺度、归一化和初始化依然关键。它改变层间连接，不决定读取哪些历史 token。','把分支输出设为零，检查整体是否仍能保留原输入。',['resnet']),
 item('mhc','mHC · 约束多分支残差','scaffold','扩展残差信息通道，同时控制多分支混合的稳定性。','mHC 对更宽的残差流和连接混合施加约束。它属于层间信号组织，和 DSA 的历史选择可以出现在同一个模型中。','多分支带来额外数据搬运和实现要求；约束不是装饰，任意混合矩阵不等价。','先检查普通 residual 的恒等路径，再观察无约束反复混合是否放大或压缩信号。',['mhc']),
 item('gated-residual','GR · Gated Residual','scaffold','通过动态门控制多个残差分支的读写。','Qwen3.8-Flash-Next 的公开 GR 设计扩宽残差流，用门调节跨层信息。它和注意力输出门、GDN 遗忘门作用位置不同。','分支增加不等于免费加深；要计入激活与带宽，并确认该版本的门和连接定义。','在 block 图上分别标出残差门、FFN 门和记忆遗忘门，解释各自控制的对象。',['qsa']),
 item('norm','LayerNorm / RMSNorm · Pre/Post Norm','scaffold','控制表示数值尺度，并改变深层网络中的优化路径。','LayerNorm 通常做去均值和方差归一化；RMSNorm 按均方根缩放。Pre/Post 描述归一化放在子层前还是后，是另一项选择。','它们不是同一个开关，也不能凭“更少运算”判断所有训练都更好。epsilon、精度和残差尺度需要核对。','对同一向量加常数，比较两类归一化输出；再沿 block 画出 norm 的位置。',['norm','transformer']),
 item('rope','RoPE · 旋转位置编码','scaffold','让 Q/K 相似度包含相对位置关系。','对成对通道施加与位置相关的旋转。它不负责缓存淘汰，也不直接决定注意力是否稀疏。二维、三维和不同伸缩方案需按模型核对。','改变位置编码或频率尺度可能破坏 checkpoint 行为。训练长度外的质量必须实测。','对两个二维向量施加相同角度旋转，核对点积；再改变两者相对角度。',['rope']),
 item('alibi','ALiBi · 位置距离偏置','scaffold','把距离倾向直接加入 attention logits。','不同头使用不同斜率的距离偏置，影响远近位置权重。它与通过旋转 Q/K 注入位置的 RoPE 是不同方案。','距离偏好不等于硬窗口：远处仍可能被读取。长度外推表现不能仅靠公式保证。','固定 QK 分数，只改变距离与斜率，观察远近位置权重怎样变化。',['alibi']),
 item('cnn','CNN / ResNet · 卷积视觉骨干','vision','利用局部连接与权重共享处理空间模式。','卷积在图像上滑动，同一组权重处理不同位置；多层和下采样建立更大感受野，残差帮助构建较深网络。','局部归纳偏置有帮助，但空间压缩可能丢细节。CNN 不因为不是 Transformer 就不能作为视觉塔。','计算两层卷积的感受野，用小目标位置任务检查下采样的代价。',['resnet']),
 item('vit','ViT · 视觉 Transformer','vision','把图像变成 patch token，再学习它们之间的关系。','将图像切块并投影为向量，加入位置信息，再交给 Transformer。视觉 token 的数量由分辨率和 patch 大小共同决定。','高分辨率会增加 token 数和注意力成本；全局表示与局部 patch 表示支持不同任务。','把 224×224 图像按 16×16 切块，先数 196 个 patch，再说明额外特殊 token 是否另计。',['vit']),
 item('swin','Swin · 分层移窗 Transformer','vision','将窗口注意力与多尺度视觉表示结合。','在局部窗口内做注意力，相邻层移动窗口，并通过 patch merging 建立层级。移窗让不同原窗口之间交换信息。','图像二维窗口不是文本因果 SWA 的同一个 mask。合并 patch 带来信息压缩。','画两个相邻层的窗口边界，看某个边缘 patch 如何接触邻窗。',['swin']),
 item('dino','DINO 家族 · 视觉表示模型','vision','用自监督学习获得可迁移的视觉特征。','DINO 描述训练方法和模型家族；具体 checkpoint 才决定 ViT 或其他 backbone。视觉塔是系统里的角色，DINO 模型可以承担这一角色。','不能把所有 DINO 版本和尺寸当成同一结构。全局 pooled 特征未必保留机器人定位需要的空间细节。','冻结视觉模型，比较 patch 特征与池化特征在位置读出上的表现。',['dino']),
 item('clip','CLIP · 图文双编码器','vision','让图像和文本表示在可比较的空间里对齐。','图像编码器与文本编码器分别处理输入，用图文配对信号训练表示。它不自带一个能够逐 token 回答问题的语言解码器。','擅长语义对齐不等于精确几何定位；编码器选型与训练目标都影响输出。','比较“语义类别正确”和“像素位置正确”两种指标是否同时改善。',['clip']),
 item('siglip','SigLIP · 图文表示家族','vision','改变图文对齐的学习信号，学习可迁移视觉语言表示。','SigLIP 使用配对的 sigmoid 学习目标；它不是与 ViT 平行的一种注意力 kernel。作为视觉塔时仍需查看具体编码器和输出接口。','训练目标变化与 backbone 变化要分开归因；不同版本的表示与分辨率设置可能不同。','在结构图中把训练目标放在 loss 旁，把 ViT 放在视觉编码器内部。',['siglip']),
 item('connector','Projector / Connector','vision','把视觉特征接到语言或世界模型的表示接口。','线性层或 MLP 可以把视觉宽度 d_v 映射到骨干宽度 D；也可配合 token 合并。它首先解决接口，不能自动补回视觉塔已丢失的信息。','维度匹配不等于语义对齐。冻结哪些模块、训练哪个阶段、保留多少 patch 都影响结果。','核对 [B,N,d_v]→[B,N,D]，再检查 pooled 输入是否还保留空间位置。',['llava']),
 item('resampler','Perceiver / Query Resampler','vision','把大量输入 token 汇聚成固定数量的潜变量。','用较少 query 对视觉输入做 cross-attention，再把固定长度表示交给后续骨干。Q 来自潜变量，K/V 来自待压缩输入。','减少 token 数会降低后续成本，也形成信息瓶颈；输出固定长度不代表无损压缩。','固定视觉塔，改变 query 数，比较成本和小物体识别/定位误差。',['perceiver']),
 item('vae','VAE / 图像与视频 Codec','generation','把高维观测压成较紧凑、可解码的表示。','编码器将像素映射到 latent，生成骨干在 latent 空间预测，解码器恢复像素。不同 codec 可采用连续或离散表示，需看具体实现。','重建误差是后续生成质量的一个上限因素。codec 的“decoder”不等于语言模型的 Decoder-only。','先仅做 encode→decode，观察细节损失，再评估生成骨干的额外误差。',['ldm']),
 item('unet','U-Net · 多尺度生成骨干','generation','在多尺度处理局部与全局信息，并保留细节路径。','下采样编码、上采样解码，同尺度之间用 skip connection 连接；扩散系统可在其中加入时间条件和注意力。','U-Net 是骨干形状，diffusion 是训练/生成过程，两者不是同一分类。','标注下采样后的分辨率，删除一个 skip 观察细节恢复变化。',['unet','ldm']),
 item('dit','DiT · Diffusion Transformer','generation','用 Transformer 作为生成过程中的预测网络。','把噪声 latent 切成 token，结合时间步与条件信息，用 Transformer 预测所需目标。其内部可见性和语言 AR decoder 未必一样。','token 数、patch 化与条件注入方式影响成本；叫 DiT 不能直接推断采用哪种噪声目标或采样器。','在图上分开标注 codec、DiT、loss 和采样器，逐个更改而不是同时替换。',['dit']),
 item('mmdit','MMDiT · 多模态生成 Transformer','generation','让文本与图像表示通过更明确的双模态路径交互。','SD3 的 MMDiT 使用模态特定处理并在注意力中交换信息；它是生成网络的设计，不是所有多模态理解模型的通称。','多模态交互方式、条件编码器和生成目标会共同影响结果，不能只比较骨干名。','追踪一条文本条件如何影响图像 token，同时指出哪些权重按模态分开。',['mmdit']),
 item('video-mixer','视频的时空联合 / 分解交互','generation','在时间和空间两个方向分配计算。','可将帧与 patch 展平一起交互，也可先空间后时间，或用时空窗口。是否因果决定模型能否只凭过去观测流式预测。','联合交互灵活但成本高；分解与窗口限制某些直接关系。视频生成也不自动等于动作条件世界模型。','数清 [帧数×patch数]，并检查未来帧是否意外进入当前预测的可见范围。',['jepa','dit']),
 item('diffusion-lm','掩码扩散语言模型 · LLaDA 路线','generation','研究逐步恢复被遮挡 token 的语言生成方式。','训练和采样围绕掩码/去噪过程组织，网络可采用不同于因果 AR 的可见性。语言模型并不在定义上必须按左到右因果分解。','多轮并行更新仍有计算与延迟成本；不能只按输出步数和 AR 比速度。','对同一长度输出统计每轮更新位置数与总前向计算，并对齐任务质量。',['llada']),
 item('rssm','RSSM · 循环状态空间世界模型','embodied','把历史信息与环境不确定性结合成可预测的潜在状态。','Dreamer 路线将确定性循环部分与随机 latent 状态结合；学习 dynamics，再用想象轨迹支持策略学习。','它和 Mamba 的 SSM 不属于同一个具体参数化；不要因为都写“状态空间”就互换实现。','分别画出 prior、观测后的 posterior 和动作条件转移，说明 rollout 时可用哪些信息。',['dreamer']),
 item('jepa','JEPA · 表示预测系统','embodied','学习在表示空间预测缺失或未来信息，减少对像素细节的直接拟合。','常见系统包含 context encoder、target encoder 与 predictor；JEPA 首先是预测目标与系统组织，内部 backbone 可以采用多种结构。','表示好不好要用下游与闭环任务评测。低 latent loss 不能直接证明控制成功或像素重建质量。','冻结/更新目标分支分别会发生什么？检查 predictor 输入中是否含有目标泄漏。',['jepa']),
 item('vla','VLA · 视觉语言动作接口','embodied','把视觉观测与语言目标转成可执行动作。','VLA 描述系统输入输出。动作可离散成 token，也可由连续动作头或生成专家输出；不能只凭 VLA 三个字推断骨干、loss 或动作时间尺度。','动作归一化、坐标系、时序和机器人形态影响迁移；语言质量不替代控制成功率。','用同一动作样本核对观测时间、预测时间、维度、单位和执行频率。',['openvla','pi0']),
 item('action-expert','Action Expert · 连续动作专家','embodied','让动作生成使用适合连续控制的专门计算分支。','π0 的 VLA Flow 系统把视觉语言表示与动作生成连接起来。这里的专家是系统分支角色，不应直接当成稀疏 MoE 路由中的一个专家。','动作分支的状态、条件与采样步骤共同决定延迟；需要真实闭环验证。','分别追踪视觉语言 token 与动作 latent，核对它们在哪些位置交换信息。',['pi0']),
 item('diffusion-policy','Diffusion Policy · 动作扩散','embodied','为多种合理动作建模，并生成一段连续动作。','在观测条件下通过去噪过程预测动作序列，可配合滚动执行。它是策略系统；内部生成网络还可有不同骨干。','多步采样增加延迟；漂亮的离线动作拟合不保证真实闭环安全和成功。','固定观测比较不同采样步数，联合记录动作误差、推理时延与任务成功率。',['diffusionPolicy']),
 item('act','ACT · 动作分块 Transformer','embodied','一次预测一段动作，减少逐步决策的噪声累积。','ACT 结合动作 chunk、Transformer 与条件变分建模；执行时还可做时序融合。chunk 长度是控制接口的一部分。','长 chunk 减少决策频率，也会减弱对突然变化的即时反馈；需联合考虑执行方式。','将同一动作轨迹按不同 chunk 长度切分，分析重叠预测如何合并以及反应延迟。',['act']),
 item('flash-attention','FlashAttention · IO 优化','execution','减少精确 attention 的中间数据搬运与显存占用。','通过分块和在线 softmax 等方法计算同一个 attention 运算，避免显式保存完整 T×T 分数矩阵。它是执行算法，可服务于相容的模型结构。','数学交互仍可为二次；实际 kernel 的精度、mask、头维度与硬件支持都有边界。','先对齐朴素实现的输出/梯度，再比较显存与时间，不能把稠密 FlashAttention 叫成稀疏结构。',['flash']),
 item('paged-attention','PagedAttention · 缓存分页','execution','减少服务中变长请求的 KV 分配浪费，并支持高效共享。','把缓存组织成可映射的块，通过逻辑到物理块映射读取；主要改变内存管理。它没有替模型决定哪些历史事实可以删除。','有分页开销和调度条件；共享前缀、并发与负载决定收益。','用多个不同长度请求统计分配量与实际使用量，区分碎片减少与模型质量。',['paged']),
 item('streaming','StreamingLLM / Attention Sinks','execution','在受限缓存中持续处理流式输入。','保留少量初始 sink token 与最近窗口是一类缓存策略。它不等于训练时采用 SWA，也不保证窗口外事实仍可精确取回。','删缓存可能改变模型行为；能持续输出与保持完整历史理解是两回事。','分别测流畅生成和很早以前的事实检索，避免只看模型没有崩溃。',['streaming']),
 item('mtp','MTP · 多 token 预测头','execution','为后续多个 token 提供额外预测信号或草稿候选。','DeepSeek-V3 的 MTP 模块参与训练，也可支持推测解码用途。它是输出/辅助模块；不是每种模型都可直接一次无条件提交多个 token。','训练目标和推理验收机制要分开；草稿必须按对应算法验证。速度取决于接受率和额外计算。','分别画出训练的辅助 loss 与推理时草稿—验证路径，记录接受 token 数。',['v3']),
];

